const courseOverview = Z('#course-overview');
let catalogNavigation = 0;
courseOverview.addEventListener('click', async event => {
  if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
  const link = event.target.closest('a[data-catalog-lesson]');
  if (!link) return;

  const navigation = ++catalogNavigation;
  if (link.hasAttribute('data-catalog-cta') || link.querySelector('.catalog-lesson-lock')) {
    event.preventDefault();
    await loadSession();
    if (navigation !== catalogNavigation) return;
    if (!hasPro()) {
      requestUpgrade(link.hash);
      return;
    }
    location.hash = link.hash;
  }
  requestAnimationFrame(() => window.scrollTo(0, 0));
});

const catalogUpgrade = courseOverview.querySelector('[data-catalog-upgrade]');
const catalogLocks = [];
for (const link of courseOverview.querySelectorAll('a[data-catalog-lesson]:not([data-catalog-cta])')) {
  const lessonId = /^#\/([\w-]+)\/\d+$/.exec(link.hash)?.[1];
  if (!lessonId || !l(lessonId) || isFreeLesson(lessonId)) continue;

  const lock = document.createElement('span');
  lock.className = 'catalog-lesson-lock';
  lock.hidden = hasPro();
  lock.title = unlockCopy.short;
  lock.innerHTML = courseLockContent();
  if (link.hasAttribute('aria-describedby')) {
    lock.id = `catalog-status-${lessonId}`;
    link.setAttribute('aria-describedby', `${link.getAttribute('aria-describedby')} ${lock.id}`);
  }
  link.append(lock);
  catalogLocks.push(lock);
}

function updateCatalogAccess() {
  if (catalogUpgrade) catalogUpgrade.hidden = hasPro();
  for (const lock of catalogLocks) {
    lock.hidden = hasPro();
    // Hidden elements referenced by aria-describedby can still be announced.
    const status = lock.querySelector('.catalog-lesson-lock__text');
    status.textContent = hasPro() ? '' : unlockCopy.short;
  }
}

let previousPro = false;
window.addEventListener('course:session', () => {
  updateCatalogAccess();
  if (previousPro === hasPro()) return;
  previousPro = hasPro();
  Bm(); Vm(); Eh.reset();
  if (X.lessonId && paidNextLesson(nf[X.lessonId], X.step)) {
    rh(uh(X.lessonId), X.step);
  }
});
void loadSession().then(updateCatalogAccess);
fg();

